-- P0 人员进修管理：年度计划、申请、可配置审批、预算预占/预算释放、待办通知和业务审计。
BEGIN;

CREATE TABLE IF NOT EXISTS "进修年度计划" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "年度" integer NOT NULL,
    "部门编号" integer NOT NULL,
    "专业方向" varchar(200) NOT NULL,
    "计划人数" integer NOT NULL DEFAULT 0,
    "预算总额" numeric(18,2) NOT NULL DEFAULT 0,
    "已占用人数" integer NOT NULL DEFAULT 0,
    "已占用预算" numeric(18,2) NOT NULL DEFAULT 0,
    "已核销金额" numeric(18,2) NOT NULL DEFAULT 0,
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "备注" varchar(1000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_进修年度计划" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_进修年度计划_部门方向" UNIQUE ("年度", "部门编号", "专业方向"),
    CONSTRAINT "ck_进修年度计划_人数" CHECK ("计划人数" >= 0 AND "已占用人数" >= 0 AND "已占用人数" <= "计划人数"),
    CONSTRAINT "ck_进修年度计划_金额" CHECK ("预算总额" >= 0 AND "已占用预算" >= 0 AND "已核销金额" >= 0 AND "已占用预算" + "已核销金额" <= "预算总额"),
    CONSTRAINT "ck_进修年度计划_状态" CHECK ("状态" IN ('草稿','已发布','已锁定','已关闭'))
);
CREATE INDEX IF NOT EXISTS "ix_进修年度计划_年度部门" ON "进修年度计划" ("年度", "部门编号", "状态");

CREATE TABLE IF NOT EXISTS "进修审批流程配置" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "业务类型" varchar(50) NOT NULL DEFAULT '人员进修',
    "版本号" integer NOT NULL,
    "名称" varchar(200) NOT NULL,
    "状态" varchar(10) NOT NULL DEFAULT '草稿',
    "流程定义" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "变更说明" varchar(1000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "发布时间" timestamp without time zone,
    CONSTRAINT "pk_进修审批流程配置" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_进修审批流程配置_版本" UNIQUE ("业务类型", "版本号"),
    CONSTRAINT "ck_进修审批流程配置_状态" CHECK ("状态" IN ('草稿','生效','停用'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_进修审批流程配置_生效" ON "进修审批流程配置" ("业务类型") WHERE "状态" = '生效';

CREATE TABLE IF NOT EXISTS "进修审批流程节点" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程配置编号" bigint NOT NULL,
    "节点序号" integer NOT NULL,
    "节点名称" varchar(100) NOT NULL,
    "节点类型" varchar(20) NOT NULL DEFAULT '审批',
    "处理角色" varchar(100),
    "是否会签" boolean NOT NULL DEFAULT false,
    "是否启用" boolean NOT NULL DEFAULT true,
    CONSTRAINT "pk_进修审批流程节点" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_进修审批流程节点_顺序" UNIQUE ("流程配置编号", "节点序号"),
    CONSTRAINT "fk_进修审批流程节点_配置" FOREIGN KEY ("流程配置编号") REFERENCES "进修审批流程配置" ("编号") ON DELETE CASCADE,
    CONSTRAINT "ck_进修审批流程节点_类型" CHECK ("节点类型" IN ('审批','备案','自动'))
);
CREATE INDEX IF NOT EXISTS "ix_进修审批流程节点_配置" ON "进修审批流程节点" ("流程配置编号", "节点序号");

CREATE TABLE IF NOT EXISTS "进修申请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "年度计划编号" bigint,
    "申请人编号" integer NOT NULL,
    "部门编号" integer NOT NULL,
    "目标医院" varchar(300) NOT NULL,
    "进修专业" varchar(200) NOT NULL,
    "进修开始日期" date NOT NULL,
    "进修结束日期" date NOT NULL,
    "进修天数" integer NOT NULL,
    "培训费" numeric(18,2) NOT NULL DEFAULT 0,
    "交通费" numeric(18,2) NOT NULL DEFAULT 0,
    "住宿费" numeric(18,2) NOT NULL DEFAULT 0,
    "补助费" numeric(18,2) NOT NULL DEFAULT 0,
    "预算金额" numeric(18,2) NOT NULL DEFAULT 0,
    "经费来源" varchar(200),
    "申请说明" varchar(3000),
    "附件路径" varchar(1000),
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "预算状态" varchar(20) NOT NULL DEFAULT '未占用',
    "流程配置编号" bigint,
    "当前节点序号" integer,
    "提交时间" timestamp without time zone,
    "完成时间" timestamp without time zone,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "备注" varchar(1000),
    CONSTRAINT "pk_进修申请" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_进修申请_计划" FOREIGN KEY ("年度计划编号") REFERENCES "进修年度计划" ("编号"),
    CONSTRAINT "fk_进修申请_流程配置" FOREIGN KEY ("流程配置编号") REFERENCES "进修审批流程配置" ("编号"),
    CONSTRAINT "ck_进修申请_日期" CHECK ("进修结束日期" >= "进修开始日期" AND "进修天数" > 0),
    CONSTRAINT "ck_进修申请_金额" CHECK ("培训费" >= 0 AND "交通费" >= 0 AND "住宿费" >= 0 AND "补助费" >= 0 AND "预算金额" >= 0),
    CONSTRAINT "ck_进修申请_状态" CHECK ("状态" IN ('草稿','审批中','已通过','已退回','已撤回','已取消','已完成')),
    CONSTRAINT "ck_进修申请_预算状态" CHECK ("预算状态" IN ('未占用','已占用','已释放','已核销'))
);
CREATE INDEX IF NOT EXISTS "ix_进修申请_申请人状态" ON "进修申请" ("申请人编号", "状态", "更新时间" DESC);
CREATE INDEX IF NOT EXISTS "ix_进修申请_计划状态" ON "进修申请" ("年度计划编号", "状态");

CREATE TABLE IF NOT EXISTS "进修审批待办" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "进修申请编号" bigint NOT NULL,
    "流程节点编号" bigint NOT NULL,
    "节点序号" integer NOT NULL,
    "接收人编号" integer,
    "接收角色" varchar(100),
    "标题" varchar(300) NOT NULL,
    "状态" varchar(20) NOT NULL DEFAULT '待处理',
    "审批意见" varchar(2000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "办理时间" timestamp without time zone,
    "到期时间" timestamp without time zone,
    CONSTRAINT "pk_进修审批待办" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_进修审批待办_申请" FOREIGN KEY ("进修申请编号") REFERENCES "进修申请" ("编号") ON DELETE CASCADE,
    CONSTRAINT "fk_进修审批待办_节点" FOREIGN KEY ("流程节点编号") REFERENCES "进修审批流程节点" ("编号"),
    CONSTRAINT "ck_进修审批待办_状态" CHECK ("状态" IN ('待处理','已通过','已退回','已撤回','已过期'))
);
CREATE INDEX IF NOT EXISTS "ix_进修审批待办_接收人状态" ON "进修审批待办" ("接收人编号", "状态", "创建时间" DESC);
CREATE INDEX IF NOT EXISTS "ix_进修审批待办_角色状态" ON "进修审批待办" ("接收角色", "状态", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "进修通知" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "进修申请编号" bigint NOT NULL,
    "接收人编号" integer,
    "接收角色" varchar(100),
    "通知类型" varchar(30) NOT NULL,
    "标题" varchar(300) NOT NULL,
    "内容" varchar(2000) NOT NULL,
    "是否已读" boolean NOT NULL DEFAULT false,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "已读时间" timestamp without time zone,
    CONSTRAINT "pk_进修通知" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_进修通知_申请" FOREIGN KEY ("进修申请编号") REFERENCES "进修申请" ("编号") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "ix_进修通知_接收人未读" ON "进修通知" ("接收人编号", "是否已读", "创建时间" DESC);
CREATE INDEX IF NOT EXISTS "ix_进修通知_角色未读" ON "进修通知" ("接收角色", "是否已读", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "进修操作审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "进修申请编号" bigint,
    "操作人编号" integer NOT NULL,
    "操作类型" varchar(50) NOT NULL,
    "原状态" varchar(20),
    "新状态" varchar(20),
    "说明" varchar(2000),
    "请求编号" varchar(64),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_进修操作审计" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_进修操作审计_申请" FOREIGN KEY ("进修申请编号") REFERENCES "进修申请" ("编号") ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS "ix_进修操作审计_申请时间" ON "进修操作审计" ("进修申请编号", "创建时间" DESC);

-- 默认流程：个人提交后依次由科主任、科教科审批；流程定义和节点可由管理人员另存新版本并发布。
INSERT INTO "进修审批流程配置" ("业务类型","版本号","名称","状态","流程定义","变更说明","创建人编号")
SELECT '人员进修', 1, '人员进修默认审批流程', '生效',
       '[{"序号":1,"名称":"科主任审批","类型":"审批","角色":"科主任"},{"序号":2,"名称":"分管领导审批","类型":"审批","角色":"分管领导"},{"序号":3,"名称":"科教科备案","类型":"备案","角色":"科研管理员"}]'::jsonb,
       'P0 默认流程：个人提交→科主任审批→分管领导审批→科教科备案',
       COALESCE((SELECT MIN("编号") FROM "人员" WHERE "是否启用"=TRUE), 1)
WHERE NOT EXISTS (SELECT 1 FROM "进修审批流程配置" WHERE "业务类型"='人员进修' AND "版本号"=1);
INSERT INTO "进修审批流程节点" ("流程配置编号","节点序号","节点名称","节点类型","处理角色","是否会签")
SELECT c."编号", x."序号", x."名称", x."类型", x."角色", false
FROM "进修审批流程配置" c
CROSS JOIN LATERAL jsonb_to_recordset(c."流程定义") AS x("序号" integer,"名称" varchar(100),"类型" varchar(20),"角色" varchar(100))
WHERE c."业务类型"='人员进修' AND c."版本号"=1
  AND NOT EXISTS (SELECT 1 FROM "进修审批流程节点" n WHERE n."流程配置编号"=c."编号");

UPDATE "系统迁移版本"
   SET "版本" = 92,
       "脚本" = '092_continuing_education_p0.sql',
       "检查摘要" = '人员进修 P0：年度计划、申请、可配置审批、预算预占释放、待办通知和业务审计',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
